export default {
  now: "09:00",
  booking: { name: "Calculus 201", start: "10:00", end: "11:00" },

  minutes(time) {
    const [hours, minutes] = time.split(":").map(Number);
    return hours * 60 + minutes;
  },

  check() {
    const time = Input1.text.trim();
    const duration = Number(Input2.text);
    const result = (reasonCode, message) => ({
      available: reasonCode === "available",
      reasonCode,
      message
    });

    if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)) {
      return result("invalid_input", "Validation error: enter time as HH:MM.");
    }
    if (!Number.isInteger(duration) || duration < 1 || duration > 120) {
      return result("duration_limit", "Validation error: duration must be 1 to 120 whole minutes.");
    }

    const start = this.minutes(time);
    const end = start + duration;

    if (start <= this.minutes(this.now)) {
      return result("past_start", "Validation error: start time must be after 09:00.");
    }
    if (end > 1440) {
      return result("invalid_input", "Validation error: the interval must end by 24:00.");
    }
    if (Switch1.isSwitchedOn) {
      return result("blocked", "Unavailable: room A101 is blocked.");
    }

    const booking = this.booking;
    if (start < this.minutes(booking.end) && end > this.minutes(booking.start)) {
      return result("overlap", `Unavailable: overlaps ${booking.name} (${booking.start}–${booking.end}).`);
    }
    return result("available", "Available: room A101 is free for this interval.");
  }
}

